function formatRemaining(usedMinutes, limitMinutes) {
  const remaining = limitMinutes - usedMinutes;
  return `${remaining} minutes remaining`;
}

module.exports = { formatRemaining };

const test = require('node:test');
const assert = require('node:assert/strict');
const { formatRemaining } = require('./formatRemaining');

test('reports remaining minutes while the allowance is available', () => {
  assert.equal(formatRemaining(45, 60), '15 minutes remaining');
});
